class Solution {
    public int longestValidSubstring(String word,List<String> forbidden){
        Set<String> banned=new HashSet<>(forbidden);
        int left=0,answer=0;
        for(int right=0;right<word.length();right++){
            for(int start=right;start>=Math.max(left,right-9);start--)if(banned.contains(word.substring(start,right+1))){
                left=start+1;
                break;
            }
            answer=Math.max(answer,right-left+1);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun longestValidSubstring(word:String,forbidden:List<String>):Int{
        val banned=forbidden.toHashSet();
        var left=0;
        var answer=0;
        for(right in word.indices){
            for(start in right downTo maxOf(left,right-9))if(word.substring(start,right+1) in banned){
                left=start+1;
                break
            };
            answer=maxOf(answer,right-left+1)
        };
        return answer
    }
}

